export function normalizePlan(value={}) {
  const source=value&&typeof value==='object'?value:{};
  return {schema:'hub-review-plan-v1',product:typeof source.product==='string'?source.product:'',steps:Object.fromEntries(STEPS.map(step=>{
    const item=source.steps?.[step.id]||{};
    return [step.id,{decision:Object.hasOwn(DECISIONS,item.decision)?item.decision:'undecided',notes:typeof item.notes==='string'?item.notes:''}];
  }))};
}
export function summarizePlan(value) {
  const plan=normalizePlan(value),counts={now:0,later:0,undecided:0};
  for(const item of Object.values(plan.steps)) counts[item.decision]++;
  return counts;
}
export function exportPlan(value) {
  const plan=normalizePlan(value);
  return ['# Plano da Review',`Produto: ${plan.product||'Ainda não definido'}`,'Modelo: review-page-creator v2.2. Preservar fluxo, visual e estrutura.','Este arquivo registra escolhas de implementação; não é uma review concluída.',...STEPS.map((step,index)=>[
    `## ${index+1}. ${step.title}`,`Etapa do modelo: ${step.phase}`,`Implementação: ${DECISIONS[plan.steps[step.id].decision]}`,`Objetivo: ${step.summary}`,'### Entradas',...step.inputs.map(v=>`- ${v}`),'### Saídas esperadas',...step.outputs.map(v=>`- ${v}`),'### Ajustes e validações',...step.adjustments.map(v=>`- ${v}`),`Próxima entrega: ${step.next}`,`Observações: ${plan.steps[step.id].notes||'Sem observações.'}`
  ].join('\n\n'))].join('\n\n');
}
